def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, list] = {}  # name -> [balance, frozen]
    history: list[tuple] = []  # inverse action for each successful non-undo op
    rejected: list[int] = []

    def parse_amount(tok: str):
        if tok and all("0" <= c <= "9" for c in tok):
            return int(tok)
        return None

    def revert(inv: tuple) -> None:
        kind = inv[0]
        if kind == "del":
            del accounts[inv[1]]
        elif kind == "bal":
            accounts[inv[1]][0] += inv[2]
        elif kind == "frozen":
            accounts[inv[1]][1] = inv[2]
        else:  # "xfer"
            _, src, dst, n = inv
            accounts[src][0] += n
            accounts[dst][0] -= n

    for idx, op in enumerate(ops):
        toks = op.split(" ")
        if any(t == "" for t in toks):
            rejected.append(idx)
            continue

        verb, args = toks[0], toks[1:]
        inverse = None

        if verb == "open" and len(args) == 2:
            name, n = args[0], parse_amount(args[1])
            if n is not None and name not in accounts:
                accounts[name] = [n, False]
                inverse = ("del", name)

        elif verb == "deposit" and len(args) == 2:
            name, n = args[0], parse_amount(args[1])
            if n is not None and n > 0 and name in accounts:
                accounts[name][0] += n
                inverse = ("bal", name, -n)

        elif verb == "withdraw" and len(args) == 2:
            name, n = args[0], parse_amount(args[1])
            if n is not None and n > 0 and name in accounts:
                acct = accounts[name]
                if not acct[1] and acct[0] >= n:
                    acct[0] -= n
                    inverse = ("bal", name, n)

        elif verb == "transfer" and len(args) == 3:
            src, dst, n = args[0], args[1], parse_amount(args[2])
            if (n is not None and n > 0 and src != dst
                    and src in accounts and dst in accounts):
                a, b = accounts[src], accounts[dst]
                if not a[1] and a[0] >= n:
                    a[0] -= n
                    b[0] += n
                    inverse = ("xfer", src, dst, n)

        elif verb == "freeze" and len(args) == 1:
            name = args[0]
            if name in accounts and not accounts[name][1]:
                accounts[name][1] = True
                inverse = ("frozen", name, False)

        elif verb == "unfreeze" and len(args) == 1:
            name = args[0]
            if name in accounts and accounts[name][1]:
                accounts[name][1] = False
                inverse = ("frozen", name, True)

        elif verb == "undo" and not args:
            if history:
                revert(history.pop())
            else:
                rejected.append(idx)
            continue

        if inverse is None:
            rejected.append(idx)
        else:
            history.append(inverse)

    balances = {name: acct[0] for name, acct in accounts.items()}
    return balances, rejected
